(function(){'use strict';var cfg=window.GORevenueIntelligence||{};var currentPostId=Number(cfg.postId||0);if(!currentPostId||!document.body||!document.body.classList.contains('single-post'))return;var SS_PAGEVIEWS='go_revenue_session_pageviews_v1';var SS_VIEWED='go_revenue_viewed_posts_v1';var LS_EDGES='go_revenue_reco_edges_v1';var sessionPageview=1;var viewed=[];var edgeMap={};var cards=[];var impressions=new Set();var lastScrollY=Math.max(0,window.scrollY||0);var lastDirection=0;var reversalShown=false;var pageStarted=performance&&performance.now?performance.now():Date.now();function safeParse(raw,fallback){try{return raw?JSON.parse(raw):fallback;}catch(e){return fallback;}}
function readSession(){try{sessionPageview=Math.max(1,Number(sessionStorage.getItem(SS_PAGEVIEWS)||0)+1);sessionStorage.setItem(SS_PAGEVIEWS,String(sessionPageview));viewed=safeParse(sessionStorage.getItem(SS_VIEWED),[]);if(!Array.isArray(viewed))viewed=[];viewed=viewed.map(Number).filter(Boolean).slice(-24);if(viewed.indexOf(currentPostId)===-1)viewed.push(currentPostId);sessionStorage.setItem(SS_VIEWED,JSON.stringify(viewed.slice(-24)));}catch(e){sessionPageview=1;viewed=[currentPostId];}
try{edgeMap=safeParse(localStorage.getItem(LS_EDGES),{});if(!edgeMap||typeof edgeMap!=='object')edgeMap={};}catch(e){edgeMap={};}}
function pushEvent(name,payload){payload=payload||{};payload.event=name;payload.reco_source_post=currentPostId;payload.reco_session_pageview=sessionPageview;window.dataLayer=window.dataLayer||[];window.dataLayer.push(payload);}
function cardAnchor(node){if(!node)return null;if(node.matches&&node.matches('a[href]'))return node;return node.querySelector?node.querySelector('a[href]'):null;}
function sourceWeight(source){source=String(source||'');if(sessionPageview<=1){if(source==='contextual-next')return 8;if(source==='inline')return 5;if(source==='post-content')return 4;return 2;}
if(sessionPageview===2){if(source==='post-content'||source==='after-card'||source==='after-related')return 6;if(source==='contextual-next')return 4;return 3;}
if(source==='after-card'||source==='after-related'||source==='after-review')return 8;if(source==='post-content')return 6;if(source==='contextual-next')return 2;return 4;}
function edgeAffinity(destinationId){var exact=edgeMap[String(currentPostId)+'>'+String(destinationId)];var global=edgeMap['*>'+String(destinationId)];var score=0;if(exact&&exact.count)score+=Math.min(16,Number(exact.count)*5);if(global&&global.count)score+=Math.min(7,Number(global.count)*1.5);return score;}
function computeScore(node){var destinationId=Number(node.getAttribute('data-go-reco-post-id')||0);var revenue=Number(node.getAttribute('data-go-reco-revenue-score')||0);var source=String(node.getAttribute('data-go-reco-source')||'related');var vertical=String(node.getAttribute('data-go-reco-vertical')||'');var score=sourceWeight(source)+Math.min(7,Math.max(0,revenue)*0.07)+edgeAffinity(destinationId);if(viewed.indexOf(destinationId)!==-1)score-=50;if(sessionPageview>=3&&source==='contextual-next')score-=4;if(sessionPageview>=3&&vertical&&vertical===String(cfg.vertical||''))score-=1.5;node.setAttribute('data-go-reco-score',score.toFixed(2));return score;}
function collectCards(){cards=Array.prototype.slice.call(document.querySelectorAll('[data-go-reco-card="1"]')).filter(function(node){var id=Number(node.getAttribute('data-go-reco-post-id')||0);return id&&id!==currentPostId&&cardAnchor(node);});cards.forEach(computeScore);}
// PHP owns contextual ranking, format diversity and manual editorial ordering.
// Local financial/session scores remain telemetry only and never move cards.
function learnEdge(destinationId){if(!destinationId)return;var nowTs=Date.now();var keys=[String(currentPostId)+'>'+String(destinationId),'*>'+String(destinationId)];keys.forEach(function(key){var row=edgeMap[key]&&typeof edgeMap[key]==='object'?edgeMap[key]:{count:0,last:0};row.count=Math.min(10,Number(row.count||0)+1);row.last=nowTs;edgeMap[key]=row;});var keysAll=Object.keys(edgeMap);if(keysAll.length>160){keysAll.sort(function(a,b){return Number(edgeMap[b].last||0)-Number(edgeMap[a].last||0);});var keep={};keysAll.slice(0,120).forEach(function(key){keep[key]=edgeMap[key];});edgeMap=keep;}
try{localStorage.setItem(LS_EDGES,JSON.stringify(edgeMap));}catch(e){}}
function bindClicks(){document.addEventListener('click',function(event){var node=event.target&&event.target.closest?event.target.closest('[data-go-reco-card="1"]'):null;if(!node)return;var id=Number(node.getAttribute('data-go-reco-post-id')||0);if(!id)return;learnEdge(id);pushEvent('go_reco_click',{reco_destination_post:id,reco_source_zone:String(node.getAttribute('data-go-reco-source')||''),reco_revenue_score:Number(node.getAttribute('data-go-reco-revenue-score')||0),reco_rank_score:Number(node.getAttribute('data-go-reco-score')||0)});},{passive:true});}
function observeImpressions(){if(!('IntersectionObserver'in window))return;var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting||entry.intersectionRatio<0.5)return;var node=entry.target;var key=String(node.getAttribute('data-go-reco-source')||'')+':'+String(node.getAttribute('data-go-reco-post-id')||'');if(impressions.has(key))return;impressions.add(key);pushEvent('go_reco_impression',{reco_destination_post:Number(node.getAttribute('data-go-reco-post-id')||0),reco_source_zone:String(node.getAttribute('data-go-reco-source')||''),reco_revenue_score:Number(node.getAttribute('data-go-reco-revenue-score')||0),reco_rank_score:Number(node.getAttribute('data-go-reco-score')||0)});observer.unobserve(node);});},{threshold:[0.5]});cards.forEach(function(node){observer.observe(node);});}
function bestReversalCard(){var eligible=cards.filter(function(node){var id=Number(node.getAttribute('data-go-reco-post-id')||0);return id&&viewed.indexOf(id)===-1&&cardAnchor(node);});eligible.sort(function(a,b){return Number(b.getAttribute('data-go-reco-score')||0)-Number(a.getAttribute('data-go-reco-score')||0);});return eligible[0]||null;}
function buildReversalBar(){var source=bestReversalCard();if(!source)return null;var anchor=cardAnchor(source);if(!anchor)return null;var id=Number(source.getAttribute('data-go-reco-post-id')||0);var headlineNode=source.querySelector('h3, strong, .go-recirc__headline, .go-inline-related__copy');var title=headlineNode?String(headlineNode.textContent||'').trim():String(anchor.textContent||'').trim();if(!title)return null;var bar=document.createElement('aside');bar.className='go-scroll-reversal-reco';bar.setAttribute('aria-hidden','true');bar.innerHTML='<span class="go-scroll-reversal-reco__eyebrow">Continuar lendo</span>'+
'<a class="go-scroll-reversal-reco__link" href="'+anchor.href.replace(/"/g,'&quot;')+'"><strong></strong><span aria-hidden="true">→</span></a>'+
'<button class="go-scroll-reversal-reco__close" type="button" aria-label="Fechar recomendação">×</button>';bar.querySelector('strong').textContent=title;bar.setAttribute('data-go-reco-card','1');bar.setAttribute('data-go-reco-post-id',String(id));bar.setAttribute('data-go-reco-source','scroll-reversal');bar.setAttribute('data-go-reco-revenue-score',source.getAttribute('data-go-reco-revenue-score')||'0');bar.setAttribute('data-go-reco-score',source.getAttribute('data-go-reco-score')||'0');document.body.appendChild(bar);bar.querySelector('.go-scroll-reversal-reco__close').addEventListener('click',function(){bar.classList.remove('is-visible');bar.setAttribute('aria-hidden','true');reversalShown=true;});return bar;}
function pageDepth(){var root=document.documentElement;var max=Math.max(1,root.scrollHeight-window.innerHeight);return Math.min(1,Math.max(0,(window.scrollY||0)/max));}
function bootScrollReversal(){var bar=buildReversalBar();if(!bar)return;window.addEventListener('scroll',function(){var y=Math.max(0,window.scrollY||0);var delta=y-lastScrollY;var direction=delta>6?1:(delta<-6?-1:lastDirection);var elapsed=(performance&&performance.now?performance.now():Date.now())-pageStarted;var depth=pageDepth();if(!reversalShown&&lastDirection===1&&direction===-1&&depth>=0.38&&elapsed>=8000){bar.classList.add('is-visible');bar.setAttribute('aria-hidden','false');reversalShown=true;pushEvent('go_reco_scroll_reversal_shown',{reco_destination_post:Number(bar.getAttribute('data-go-reco-post-id')||0),scroll_depth:+depth.toFixed(3)});}
if(depth<0.16){bar.classList.remove('is-visible');bar.setAttribute('aria-hidden','true');}
lastScrollY=y;lastDirection=direction;},{passive:true});}
function boot(){readSession();collectCards();if(!cards.length)return;bindClicks();observeImpressions();if(cfg.scrollReversalEnabled===true)bootScrollReversal();document.documentElement.setAttribute('data-go-session-pageview',String(sessionPageview));pushEvent('go_reco_session_context',{reco_card_count:cards.length,reco_viewed_count:viewed.length});window.addEventListener('pagehide',function(){var activeMs=0;try{var snapshot=window.GOAdsDiagnostics&&typeof window.GOAdsDiagnostics.snapshot==='function'?window.GOAdsDiagnostics.snapshot():null;activeMs=snapshot&&snapshot.rpmTelemetry&&snapshot.rpmTelemetry.activeTimeYield?Number(snapshot.rpmTelemetry.activeTimeYield.activeMs||0):0;}catch(e){}
pushEvent('go_reader_session_value',{reader_active_ms:Math.round(activeMs),reco_impressions:impressions.size});},{once:true});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();})();
